#include <iostream>
#include <string>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

long long dp[31][31][31][450];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string S;
    long long K;
    if (!(cin >> S >> K)) return 0;
    int n = S.size();
    vector<int> posK, posE, posY;
    for (int i = 0; i < n; ++i) {
        if (S[i] == 'K') posK.push_back(i);
        else if (S[i] == 'E') posE.push_back(i);
        else posY.push_back(i);
    }
    int nK = posK.size(), nE = posE.size(), nY = posY.size();
    int max_inv = n * (n - 1) / 2;
    dp[0][0][0][0] = 1;

    for (int i = 0; i <= nK; ++i) {
        for (int j = 0; j <= nE; ++j) {
            for (int k = 0; k <= nY; ++k) {
                for (int inv = 0; inv <= max_inv; ++inv) {
                    long long cur = dp[i][j][k][inv];
                    if (!cur) continue;
                    // Try placing K
                    if (i < nK) {
                        int cost = 0;
                        for (int e = 0; e < j; ++e) if (posE[e] > posK[i]) cost++;
                        for (int y = 0; y < k; ++y) if (posY[y] > posK[i]) cost++;
                        dp[i + 1][j][k][inv + cost] += cur;
                    }
                    // Try placing E
                    if (j < nE) {
                        int cost = 0;
                        for (int kk = 0; kk < i; ++kk) if (posK[kk] > posE[j]) cost++;
                        for (int y = 0; y < k; ++y) if (posY[y] > posE[j]) cost++;
                        dp[i][j + 1][k][inv + cost] += cur;
                    }
                    // Try placing Y
                    if (k < nY) {
                        int cost = 0;
                        for (int kk = 0; kk < i; ++kk) if (posK[kk] > posY[k]) cost++;
                        for (int e = 0; e < j; ++e) if (posE[e] > posY[k]) cost++;
                        dp[i][j][k + 1][inv + cost] += cur;
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int inv = 0; inv <= min((long long)max_inv, K); ++inv) {
        ans += dp[nK][nE][nY][inv];
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<pair<double, double>> P(n + 1), Q(n + 1);
    for (int i = 1; i <= n; ++i) cin >> P[i].first >> P[i].second;
    for (int i = 1; i <= n; ++i) cin >> Q[i].first >> Q[i].second;

    vector<vector<double>> cost(n + 1, vector<double>(n + 1));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            cost[i][j] = hypot(P[i].first - Q[j].first, P[i].second - Q[j].second);
        }
    }

    vector<double> u(n + 1), v(n + 1);
    vector<int> p(n + 1), way(n + 1);
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        vector<double> minv(n + 1, 1e18);
        vector<char> used(n + 1, false);
        do {
            used[j0] = true;
            int i0 = p[j0];
            double delta = 1e18;
            int j1 = 0;
            for (int j = 1; j <= n; ++j) {
                if (!used[j]) {
                    double cur = cost[i0][j] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }

    vector<int> ans(n + 1);
    for (int j = 1; j <= n; ++j) {
        ans[p[j]] = j;
    }
    for (int i = 1; i <= n; ++i) {
        cout << ans[i] << (i == n ? "" : " ");
    }
    cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long P, B;
    int N, M;
    if (!(cin >> P >> B >> N >> M)) return 0;

    int V = N + 1;
    if (P >= V) {
        cout << "Yes\n";
        return 0;
    }

    vector<int> adj(V, 0);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        u--; // L_i - 1
        // v is R_i
        adj[u] |= (1 << v);
        adj[v] |= (1 << u);
    }

    int total_masks = 1 << V;
    vector<int> is_indep(total_masks, 0);
    is_indep[0] = 1;
    for (int mask = 1; mask < total_masks; ++mask) {
        int v = __builtin_ctz(mask);
        int prev = mask ^ (1 << v);
        if (is_indep[prev] && !(prev & adj[v])) {
            is_indep[mask] = 1;
        }
    }

    // Fast Zeta Transform on is_indep
    vector<long long> f(total_masks);
    for (int i = 0; i < total_masks; ++i) f[i] = is_indep[i];

    for (int i = 0; i < V; ++i) {
        for (int mask = 0; mask < total_masks; ++mask) {
            if (mask & (1 << i)) {
                f[mask] += f[mask ^ (1 << i)];
            }
        }
    }

    // Number of proper colorings with k colors is:
    // sum_{S} (-1)^{V - |S|} f(S)^k
    // Check modulo two primes:
    long long MOD1 = 998244353;
    long long MOD2 = 1000000007;

    auto power = [](long long base, long long exp, long long mod) {
        long long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    };

    long long sum1 = 0, sum2 = 0;
    for (int mask = 0; mask < total_masks; ++mask) {
        int sz = __builtin_popcount(mask);
        long long sign = ((V - sz) % 2 == 0) ? 1 : -1;

        long long term1 = power(f[mask] % MOD1, P, MOD1);
        long long term2 = power(f[mask] % MOD2, P, MOD2);

        sum1 = (sum1 + sign * term1) % MOD1;
        sum2 = (sum2 + sign * term2) % MOD2;
    }
    sum1 = (sum1 % MOD1 + MOD1) % MOD1;
    sum2 = (sum2 % MOD2 + MOD2) % MOD2;

    if (sum1 != 0 || sum2 != 0) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

using namespace std;

struct Edge {
    int to;
    int weight;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<pair<int, int>>> out_edges(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, c;
        cin >> u >> v >> c;
        out_edges[u].push_back({v, c});
    }

    // Graph on H
    vector<vector<Edge>> adj(n + 1);
    for (int u = 1; u <= n; ++u) {
        if (out_edges[u].size() <= 1) continue;
        int v0 = out_edges[u][0].first;
        int c0 = out_edges[u][0].second;
        for (size_t j = 1; j < out_edges[u].size(); ++j) {
            int vj = out_edges[u][j].first;
            int cj = out_edges[u][j].second;
            int w = c0 ^ cj;
            adj[v0].push_back({vj, w});
            adj[vj].push_back({v0, w});
        }
    }

    vector<int> H(n + 1, -1);
    bool possible = true;
    for (int i = 1; i <= n; ++i) {
        if (H[i] != -1) continue;
        H[i] = 0;
        vector<int> q = {i};
        int head = 0;
        while (head < (int)q.size()) {
            int u = q[head++];
            for (auto& edge : adj[u]) {
                int v = edge.to;
                int req = H[u] ^ edge.weight;
                if (H[v] == -1) {
                    H[v] = req;
                    q.push_back(v);
                } else if (H[v] != req) {
                    possible = false;
                    break;
                }
            }
            if (!possible) break;
        }
        if (!possible) break;
    }

    if (!possible) {
        cout << -1 << "\n";
        return 0;
    }

    string D(n, '0');
    for (int u = 1; u <= n; ++u) {
        if (out_edges[u].empty()) {
            D[u - 1] = '0';
        } else {
            int v = out_edges[u][0].first;
            int c = out_edges[u][0].second;
            int du = H[u] ^ H[v] ^ c;
            D[u - 1] = (du == 1 ? '1' : '0');
        }
    }
    cout << D << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

const long long MOD = 998244353;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    string X;
    if (!(cin >> n >> X)) return 0;

    vector<int> divs;
    for (int d = 1; d * d <= n; ++d) {
        if (n % d == 0) {
            if ((n / d) % 2 == 1) divs.push_back(d);
            int d2 = n / d;
            if (d2 != d && (n / d2) % 2 == 1) divs.push_back(d2);
        }
    }
    sort(divs.begin(), divs.end());

    int num_divs = divs.size();
    vector<long long> C(num_divs);

    for (int idx = 0; idx < num_divs; ++idx) {
        int d = divs[idx];
        long long val = 0;
        for (int i = 0; i < d; ++i) {
            val = (val * 2 + (X[i] - '0')) % MOD;
        }

        string S(n, '0');
        for (int i = 0; i < n; ++i) {
            int q = i / d;
            int r = i % d;
            char bit = X[r];
            if (q % 2 == 1) {
                bit = (bit == '0' ? '1' : '0');
            }
            S[i] = bit;
        }

        if (S <= X) {
            val = (val + 1) % MOD;
        }
        C[idx] = val;
    }

    vector<long long> f = C;
    for (int i = 0; i < num_divs; ++i) {
        int d = divs[i];
        for (int j = 0; j < i; ++j) {
            int d2 = divs[j];
            if (d % d2 == 0 && (d / d2) % 2 == 1) {
                f[i] = (f[i] - f[j] + MOD) % MOD;
            }
        }
    }

    long long ans = 0;
    for (int i = 0; i < num_divs; ++i) {
        ans = (ans + f[i] * (2LL * divs[i])) % MOD;
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

typedef __int128_t int128;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    long long H_in;
    if (!(cin >> n >> H_in)) return 0;
    int128 H = H_in;

    map<long long, long long> by_t;
    for (int i = 0; i < n; ++i) {
        long long t, d;
        cin >> t >> d;
        by_t[t] = max(by_t[t], d);
    }

    vector<long long> unique_t;
    vector<long long> val_d;
    for (auto& p : by_t) {
        unique_t.push_back(p.first);
        val_d.push_back(p.second);
    }
    int m = unique_t.size();

    vector<int128> max_td(m);
    int128 cur = 0;
    for (int i = 0; i < m; ++i) {
        cur = max(cur, (int128)unique_t[i] * val_d[i]);
        max_td[i] = cur;
    }

    vector<int128> max_d(m);
    cur = 0;
    for (int i = m - 1; i >= 0; --i) {
        cur = max(cur, (int128)val_d[i]);
        max_d[i] = cur;
    }

    auto sum_interval = [](int128 L, int128 R, int128 C1, int128 C2) -> int128 {
        if (L > R) return 0;
        if (C2 == 0) return C1 * (R - L + 1);
        int128 k_cross = (C1 + C2 - 1) / C2;
        int128 total = 0;
        if (L <= k_cross - 1) {
            int128 r1 = min(R, k_cross - 1);
            total += C1 * (r1 - L + 1);
        }
        if (max(L, k_cross) <= R) {
            int128 l2 = max(L, k_cross);
            int128 cnt = R - l2 + 1;
            int128 sum_k = (l2 + R) * cnt / 2;
            total += sum_k * C2;
        }
        return total;
    };

    auto total_damage = [&](int128 T) -> int128 {
        int128 total = 0;
        int128 prev = 0;
        for (int i = 0; i < m; ++i) {
            int128 t_curr = unique_t[i];
            if (prev + 1 > T) break;
            int128 L = prev + 1;
            int128 R = min(T, t_curr);
            int128 C1 = (i > 0 ? max_td[i - 1] : 0);
            int128 C2 = max_d[i];
            total += sum_interval(L, R, C1, C2);
            prev = t_curr;
            if (prev >= T) break;
        }
        if (T > prev) {
            total += (T - prev) * max_td[m - 1];
        }
        return total;
    };

    long long low = 1, high = 2000000000000000000LL;
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (total_damage(mid) >= H) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

long long gcd(long long a, long long b) {
    return b == 0 ? a : gcd(b, a % b);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    long long N, K;
    if (!(cin >> N >> K)) return 0;

    if (N % 2 == 0) {
        cout << -1 << "\n";
        return 0;
    }

    long long g = gcd(N, K);
    long long n = N / g;

    vector<vector<int>> grid(n, vector<int>(g));
    for (int r = 0; r < n; ++r) {
        long long base = (1LL * r * K) % N;
        for (int c = 0; c < g; ++c) {
            grid[r][c] = (base + c) % N;
        }
    }

    vector<pair<int, int>> edges;

    // 1. Vertical edges in odd-numbered columns (c = 0, 2, 4, ...):
    for (int c = 0; c < g; c += 2) {
        for (int r = 0; r < (n - 1) / 2; ++r) {
            edges.push_back({grid[2 * r][c], grid[2 * r + 1][c]});
        }
    }

    // 2. Horizontal edges from odd-numbered columns (c = 0, 2, 4, ... < g - 1):
    for (int c = 0; c < g - 1; c += 2) {
        for (int r = 0; r < (n - 1) / 2; ++r) {
            edges.push_back({grid[2 * r][c], grid[2 * r][c + 1]});
        }
    }

    // 3. Horizontal edges from even-numbered columns (c = 1, 3, 5, ... < g - 1):
    for (int c = 1; c < g - 1; c += 2) {
        edges.push_back({grid[n - 2][c], grid[n - 2][c + 1]});
    }

    cout << edges.size() << "\n";
    for (auto& e : edges) {
        cout << e.first << " " << e.second << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <set>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> C(n + 1);
    set<int> active;
    for (int i = 1; i <= n; ++i) {
        cin >> C[i];
        active.insert(C[i]);
    }
    int q;
    cin >> q;
    vector<int> D(q);
    for (int i = 0; i < q; ++i) {
        cin >> D[i];
    }

    multiset<int> top_diffs;
    multiset<int> bot_diffs;
    long long sum_top = 0;
    int k_drop = k - 1;

    auto add_diff = [&](int diff) {
        if (k_drop == 0) return;
        if ((int)top_diffs.size() < k_drop) {
            top_diffs.insert(diff);
            sum_top += diff;
        } else if (diff > *top_diffs.begin()) {
            int smallest = *top_diffs.begin();
            top_diffs.erase(top_diffs.begin());
            sum_top -= smallest;
            bot_diffs.insert(smallest);

            top_diffs.insert(diff);
            sum_top += diff;
        } else {
            bot_diffs.insert(diff);
        }
    };

    auto erase_diff = [&](int diff) {
        if (k_drop == 0) return;
        auto it = bot_diffs.find(diff);
        if (it != bot_diffs.end()) {
            bot_diffs.erase(it);
        } else {
            auto it2 = top_diffs.find(diff);
            if (it2 != top_diffs.end()) {
                top_diffs.erase(it2);
                sum_top -= diff;
                if (!bot_diffs.empty()) {
                    auto it_max = prev(bot_diffs.end());
                    int val = *it_max;
                    bot_diffs.erase(it_max);
                    top_diffs.insert(val);
                    sum_top += val;
                }
            }
        }
    };

    // Initialize diffs
    auto it = active.begin();
    int prev_val = *it;
    it++;
    for (; it != active.end(); ++it) {
        add_diff(*it - prev_val);
        prev_val = *it;
    }

    auto get_ans = [&]() -> long long {
        if ((int)active.size() <= k) return 0;
        int span = *active.rbegin() - *active.begin();
        return span - sum_top;
    };

    cout << get_ans() << "\n";
    for (int i = 0; i < q; ++i) {
        int val = C[D[i]];
        auto it_cur = active.find(val);
        bool has_prev = (it_cur != active.begin());
        bool has_next = (next(it_cur) != active.end());

        if (has_prev && has_next) {
            int p = *prev(it_cur);
            int s = *next(it_cur);
            erase_diff(val - p);
            erase_diff(s - val);
            add_diff(s - p);
        } else if (has_prev) {
            int p = *prev(it_cur);
            erase_diff(val - p);
        } else if (has_next) {
            int s = *next(it_cur);
            erase_diff(s - val);
        }
        active.erase(it_cur);
        cout << get_ans() << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

const long long INF = 1e18;

struct RevEdge {
    int u;
    long long w;
    long long P;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int N, M, src, dst;
    if (!(cin >> N >> M >> src >> dst)) return 0;

    struct Line {
        int L;
        vector<int> stations;
        vector<long long> weights;
    };

    vector<Line> lines(M);
    vector<vector<pair<int, long long>>> adj(N);

    for (int i = 0; i < M; ++i) {
        cin >> lines[i].L;
        lines[i].stations.resize(lines[i].L);
        for (int j = 0; j < lines[i].L; ++j) cin >> lines[i].stations[j];
        lines[i].weights.resize(lines[i].L - 1);
        for (int j = 0; j < lines[i].L - 1; ++j) {
            cin >> lines[i].weights[j];
            int u = lines[i].stations[j];
            int v = lines[i].stations[j + 1];
            long long w = lines[i].weights[j];
            adj[u].push_back({v, w});
            adj[v].push_back({u, w});
        }
    }

    // 1. Dijkstra from dst
    vector<long long> d_normal(N, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    d_normal[dst] = 0;
    pq.push({0, dst});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > d_normal[u]) continue;
        for (auto& edge : adj[u]) {
            int v = edge.first;
            long long w = edge.second;
            if (d + w < d_normal[v]) {
                d_normal[v] = d + w;
                pq.push({d + w, v});
            }
        }
    }

    // 2. Build rev_edges
    vector<vector<RevEdge>> rev_edges(N);
    for (int l = 0; l < M; ++l) {
        int L = lines[l].L;
        auto& st = lines[l].stations;
        auto& wt = lines[l].weights;
        vector<long long> pref(L, 0);
        for (int j = 0; j < L - 1; ++j) {
            pref[j + 1] = pref[j] + wt[j];
        }
        long long total_len = pref[L - 1];
        int T_fwd = st[L - 1];
        int T_bwd = st[0];

        // Forward edges: st[j] -> st[j+1]
        for (int j = 0; j < L - 1; ++j) {
            int u = st[j];
            int v = st[j + 1];
            long long w = wt[j];
            long long P = (total_len - pref[j]) + d_normal[T_fwd];
            rev_edges[v].push_back({u, w, P});
        }

        // Backward edges: st[j+1] -> st[j]
        for (int j = 0; j < L - 1; ++j) {
            int u = st[j + 1];
            int v = st[j];
            long long w = wt[j];
            long long P = pref[j + 1] + d_normal[T_bwd];
            rev_edges[v].push_back({u, w, P});
        }
    }

    // 3. Dijkstra backwards from dst on game DP
    vector<long long> dp(N, INF);
    dp[dst] = 0;
    pq.push({0, dst});
    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d > dp[v]) continue;
        if (v == src) break;
        for (auto& edge : rev_edges[v]) {
            int u = edge.u;
            long long cand = max(edge.w + d, edge.P);
            if (cand < dp[u]) {
                dp[u] = cand;
                pq.push({cand, u});
            }
        }
    }

    cout << dp[src] << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;
    vector<int> C(n);
    vector<int> total_cnt(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        cin >> C[i];
        total_cnt[C[i]]++;
    }

    vector<int> A(2 * n);
    for (int i = 0; i < n; ++i) {
        A[i] = A[i + n] = C[i];
    }

    vector<int> b(n + 1, 0);
    vector<int> in_win(n + 1, 0);
    int total_boxes = 0;
    long long ans_balls = 0;

    auto add_color = [&](int c) -> bool {
        bool need_box = (in_win[c] % k == 0);
        if (need_box) {
            if (total_boxes == m) return false;
            total_boxes++;
            long long old_cap = min((long long)total_cnt[c], 1LL * b[c] * k);
            b[c]++;
            long long new_cap = min((long long)total_cnt[c], 1LL * b[c] * k);
            ans_balls += (new_cap - old_cap);
        }
        in_win[c]++;
        return true;
    };

    auto remove_color = [&](int c) {
        in_win[c]--;
        if (in_win[c] % k == 0) {
            total_boxes--;
            long long old_cap = min((long long)total_cnt[c], 1LL * b[c] * k);
            b[c]--;
            long long new_cap = min((long long)total_cnt[c], 1LL * b[c] * k);
            ans_balls += (new_cap - old_cap);
        }
    };

    int R = 0;
    while (R < n) {
        if (!add_color(A[R])) break;
        R++;
    }

    for (int L = 0; L < n; ++L) {
        cout << ans_balls << "\n";
        if (R == L) {
            R++;
        } else {
            remove_color(A[L]);
        }
        while (R < L + n) {
            if (!add_color(A[R])) break;
            R++;
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

using namespace std;

typedef __int128_t int128;

int128 gcd128(int128 a, int128 b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

struct Frac {
    int128 num, den;
    Frac(int128 n = 0, int128 d = 1) {
        if (d < 0) { n = -n; d = -d; }
        int128 g = gcd128(n, d);
        num = n / g;
        den = d / g;
    }
    bool operator<(const Frac& o) const {
        return num * o.den < o.num * den;
    }
    bool operator<=(const Frac& o) const {
        return num * o.den <= o.num * den;
    }
    bool operator>(const Frac& o) const {
        return num * o.den > o.num * den;
    }
    Frac operator*(const Frac& o) const {
        return Frac(num * o.num, den * o.den);
    }
    Frac operator+(const Frac& o) const {
        return Frac(num * o.den + o.num * den, den * o.den);
    }
    Frac operator-(const Frac& o) const {
        return Frac(num * o.den - o.num * den, den * o.den);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n;
    if (!(cin >> n)) return 0;
    vector<long long> A(n), B(n);
    for (int i = 0; i < n; ++i) cin >> A[i];
    for (int i = 0; i < n; ++i) cin >> B[i];

    // Case 1: slope s in [-1, 1], cost is sum |B_i - s * A_i|
    struct Pt1 {
        Frac s;
        int128 w;
        bool operator<(const Pt1& o) const {
            return s < o.s;
        }
    };
    vector<Pt1> pts1;
    int128 const1 = 0;
    int128 total_w1 = 0;
    for (int i = 0; i < n; ++i) {
        if (A[i] == 0) {
            const1 += abs(B[i]);
        } else {
            Frac si(B[i], A[i]);
            int128 w = abs(A[i]);
            pts1.push_back({si, w});
            total_w1 += w;
        }
    }
    sort(pts1.begin(), pts1.end());
    Frac best_s(0, 1);
    int128 cur_w1 = 0;
    for (auto& pt : pts1) {
        cur_w1 += pt.w;
        if (cur_w1 * 2 >= total_w1) {
            best_s = pt.s;
            break;
        }
    }
    if (best_s < Frac(-1, 1)) best_s = Frac(-1, 1);
    if (best_s > Frac(1, 1)) best_s = Frac(1, 1);

    Frac val1(const1, 1);
    for (int i = 0; i < n; ++i) {
        if (A[i] != 0) {
            Frac diff = Frac(B[i], 1) - best_s * Frac(A[i], 1);
            if (diff.num < 0) diff.num = -diff.num;
            val1 = val1 + diff;
        }
    }

    // Case 2: slope t in [-1, 1], cost is sum |A_i - t * B_i|
    vector<Pt1> pts2;
    int128 const2 = 0;
    int128 total_w2 = 0;
    for (int i = 0; i < n; ++i) {
        if (B[i] == 0) {
            const2 += abs(A[i]);
        } else {
            Frac ti(A[i], B[i]);
            int128 w = abs(B[i]);
            pts2.push_back({ti, w});
            total_w2 += w;
        }
    }
    sort(pts2.begin(), pts2.end());
    Frac best_t(0, 1);
    int128 cur_w2 = 0;
    for (auto& pt : pts2) {
        cur_w2 += pt.w;
        if (cur_w2 * 2 >= total_w2) {
            best_t = pt.s;
            break;
        }
    }
    if (best_t < Frac(-1, 1)) best_t = Frac(-1, 1);
    if (best_t > Frac(1, 1)) best_t = Frac(1, 1);

    Frac val2(const2, 1);
    for (int i = 0; i < n; ++i) {
        if (B[i] != 0) {
            Frac diff = Frac(A[i], 1) - best_t * Frac(B[i], 1);
            if (diff.num < 0) diff.num = -diff.num;
            val2 = val2 + diff;
        }
    }

    Frac ans = (val1 < val2 ? val1 : val2);
    // Print numerator and denominator
    auto print128 = [](int128 x) {
        if (x == 0) {
            cout << 0;
            return;
        }
        string s;
        while (x > 0) {
            s.push_back((char)('0' + (x % 10)));
            x /= 10;
        }
        reverse(s.begin(), s.end());
        cout << s;
    };
    print128(ans.num);
    cout << " ";
    print128(ans.den);
    cout << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

vector<int> prefix_function(const string& s) {
    int n = s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) j = pi[j - 1];
        if (s[i] == s[j]) j++;
        pi[i] = j;
    }
    return pi;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string s, t;
    if (!(cin >> s >> t)) return 0;
    int len_s = s.size(), len_t = t.size();

    int reps = (len_t + len_s - 1) / len_s + 2;
    string s_rep = "";
    for (int i = 0; i < reps; ++i) s_rep += s;

    string pattern = t + "#" + s_rep;
    vector<int> pi = prefix_function(pattern);

    vector<bool> match(len_s, false);
    for (size_t i = len_t + 1; i < pattern.size(); ++i) {
        if (pi[i] == len_t) {
            int start_idx_in_srep = i - 2 * len_t;
            if (start_idx_in_srep < len_s) {
                match[start_idx_in_srep] = true;
            }
        }
    }

    vector<int> to(len_s, -1);
    vector<int> in_deg(len_s, 0);
    for (int i = 0; i < len_s; ++i) {
        if (match[i]) {
            to[i] = (i + len_t) % len_s;
            in_deg[to[i]]++;
        }
    }

    // Detect cycle and find longest path
    // 0: unvisited, 1: visiting, 2: visited
    vector<int> state(len_s, 0);
    vector<int> dp(len_s, 0);
    bool has_cycle = false;

    auto dfs = [&](auto& self, int u) -> int {
        state[u] = 1;
        int max_len = 0;
        if (to[u] != -1) {
            int v = to[u];
            if (state[v] == 1) {
                has_cycle = true;
            } else {
                if (state[v] == 0) self(self, v);
                max_len = 1 + dp[v];
            }
        }
        state[u] = 2;
        dp[u] = max_len;
        return dp[u];
    };

    for (int i = 0; i < len_s; ++i) {
        if (state[i] == 0 && match[i]) {
            dfs(dfs, i);
        }
    }

    if (has_cycle) {
        cout << -1 << "\n";
    } else {
        int ans = 0;
        for (int i = 0; i < len_s; ++i) {
            ans = max(ans, dp[i]);
        }
        cout << ans << "\n";
    }
    return 0;
}

#include <iostream>
