using namespace std;

int dp[305][305];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string S;
    int K;
    if (!(cin >> S >> K)) return 0;
    int n = S.size();

    for (int len = 1; len <= n; ++len) {
        for (int l = 0; l <= n - len; ++l) {
            int r = l + len - 1;
            int ans = 1 + dp[l + 1][r];
            for (int m = l; m < r; ++m) {
                ans = min(ans, dp[l][m] + dp[m + 1][r]);
            }
            if (S[l] == 'o') {
                for (int m = l + 1; m <= r; ++m) {
                    if (S[m] == 'f' && dp[l + 1][m - 1] == 0) {
                        int rem = max(0, dp[m + 1][r] - K);
                        ans = min(ans, rem);
                    }
                }
            }
            dp[l][r] = ans;
        }
    }

    cout << dp[0][n - 1] << "\n";
    return 0;
}
